'use client';

/**
 * @file buttonHitArea.ts
 * @input Uses createSharedContext and the touch hit-area options type
 * @output Exports ButtonHitAreaContext, the touch hit-area options a Button
 *   passes to useTouchHitArea, and BUTTON_HIT_AREA, their default
 * @position Internal to Core. A Core part that renders a Button and needs a
 *   different band, such as InputClearButton, provides its own options.
 */

import {createSharedContext} from '../utils/sharedContext';
import type {TouchHitAreaOptions} from '../utils/touchHitArea';

// The band is on the content wrapper, so a band tap lands on a descendant.
// Button's content never paints past its box, so such a tap nearer a
// neighbour is the neighbour's, not this button's.
export const BUTTON_HIT_AREA: TouchHitAreaOptions = {
  ownsDescendantTouches: false,
};

export const ButtonHitAreaContext = createSharedContext<TouchHitAreaOptions>(
  'ButtonHitAreaContext',
  1,
  BUTTON_HIT_AREA,
);
ButtonHitAreaContext.displayName = 'ButtonHitAreaContext';

// Copyright (c) Meta Platforms, Inc. and affiliates.

'use client';

/**
 * @file Field.tsx
 * @input Uses React, StyleX, BaseProps, FieldLabel/FieldStatus, FormLayoutContext, Text, VisuallyHidden, theme/status utilities
 * @output Exports Field component, FieldProps
 * @position Core implementation; consumed by index.ts, tested by Field.test.tsx
 *
 * SYNC: When modified, update these files to stay in sync:
 * - /packages/core/src/Field/Field.doc.mjs (props table, features, implementation notes)
 * - /packages/core/src/Field/Field.test.tsx (tests for new/changed behavior)
 * - /packages/core/src/Field/index.ts (exports if types change)
 * - /apps/storybook/stories/Field.stories.tsx (storybook stories)
 * - /packages/cli/assets/templates/blocks/components/Field/ (showcase blocks)
 */

import {type ReactNode, use} from 'react';
import * as stylex from '@stylexjs/stylex';
import type {BaseProps} from '@astryxdesign/core/BaseProps';
import type {SizeValue} from '@astryxdesign/core/utils';
import {FieldLabel} from './FieldLabel';
import {FieldStatus} from '@astryxdesign/core/FieldStatus';
import {useFieldStatusAnnouncement} from '../FieldStatus/useFieldStatusAnnouncement';
import {spacingVars, borderVars, sizeVars} from '@astryxdesign/core/theme/tokens.stylex';
import type {IconType} from '@astryxdesign/core/Icon';
import {mergeProps} from '@astryxdesign/core/utils';
import {useDevWarning} from '@astryxdesign/core/hooks';
import {FormLayoutContext} from '@astryxdesign/core/FormLayout';
import {Text} from '@astryxdesign/core/Text';
import {VisuallyHidden} from '@astryxdesign/core/VisuallyHidden';
import {themeProps} from '@astryxdesign/core/utils';
import type {FieldStatusPlacement} from './fieldStatusPlacement';

const styles = stylex.create({
  container: {
    display: 'flex',
    flexDirection: 'column',
    // The Field root owns the local stacking boundary (AST-027): the input
    // wrapper's z-index (1, above the attached status box) and the attached
    // status layer (-1) order parts inside this surface only. Without this,
    // detached/tooltip fields — whose input wrapper renders outside the
    // attached-status wrapper — compete with page-level stacking (#5689).
    isolation: 'isolate',
    // The Field root is the flex/grid item a row actually sizes. With the
    // automatic minimum it held a filter bar at its controls' intrinsic
    // widths (a native input's ~20ch, a Selector's full value), so the row
    // overflowed on phones; the reset lets the row shrink the whole field.
    minWidth: 0,
  },
  containerGap: {
    gap: spacingVars['--spacing-1'],
  },
  horizontalLabels: {
    display: 'contents',
  },
  horizontalLabelAlign: {
    // Align label text with input text by matching the input wrapper's
    // top border + top padding. Works for both single-line inputs and
    // textareas (labels stay top-aligned, not vertically centered).
    paddingTop: `calc(${borderVars['--border-width']} + ${spacingVars['--spacing-1']})`,
  },
  inputStatusWrapper: {
    display: 'flex',
    flexDirection: 'column',
    isolation: 'isolate',
    // Extend an attached FieldStatus behind the lower half of the control.
    // Half-height is the maximum effective corner radius CSS can render, even
    // when a theme uses a pill value such as --radius-full (9999px).
    '--_field-status-overlap': {
      default: `calc(${sizeVars['--size-element-md']} / 2)`,
      ':has(> [data-size="sm"])': `calc(${sizeVars['--size-element-sm']} / 2)`,
      ':has(> [data-size="lg"])': `calc(${sizeVars['--size-element-lg']} / 2)`,
    },
  },
  attachedStatusLayer: {
    // Keep the overlapping background below both Astryx inputs and custom
    // controls. The isolated wrapper contains this negative stacking layer.
    position: 'relative',
    zIndex: -1,
  },
});

// Dynamic style for the consumer-controlled field width. Numbers are treated
// as pixels by StyleX; strings (e.g. '100%') are used as-is.
const dynamicStyles = stylex.create({
  width: (width: SizeValue | null) => ({width}),
});

export type {SizeValue} from '@astryxdesign/core/utils';

export type FieldStatusType = 'warning' | 'error' | 'success';

export interface FieldStatusInput {
  /**
   * The type of status to display.
   */
  type: FieldStatusType;
  /**
   * Optional message to display below the input.
   */
  message?: string;
  /**
   * ID for the status message element (use for aria-describedby on the input).
   */
  messageID?: string;
}

export interface FieldProps extends Omit<
  BaseProps<HTMLDivElement>,
  'children'
> {
  /** Ref forwarded to the root element */
  ref?: React.Ref<HTMLDivElement>;
  /**
   * Label text for the field (always rendered for accessibility).
   */
  label: string;
  /**
   * Whether to visually hide the label and description (still accessible to screen readers).
   * @default false
   */
  isLabelHidden?: boolean;
  /**
   * Description text displayed between the label and input.
   * Hidden when isLabelHidden is true.
   */
  description?: string;
  /**
   * ID of the input element this label points AT (used as the label's
   * `htmlFor`). This is the id of the *control*, not of the label element —
   * see `labelID` for the latter.
   */
  inputID: string;
  /**
   * The `id` applied TO the label element itself (distinct from `inputID`,
   * which is the control the label points at). A grouping control
   * (radiogroup, checkbox group) references this via `aria-labelledby` to take
   * the label as its accessible name. Pair with `isGroupLabel`.
   */
  labelID?: string;
  /**
   * When the field wraps a group of controls rather than a single input, set
   * this so the label renders as a non-`<label>` element (a `<span>`): a
   * `<label>` semantically names one control and can't be associated with a
   * group. Pair with `labelID` + `aria-labelledby` on the group.
   * @default false
   */
  isGroupLabel?: boolean;
  /**
   * ID for the description element (use for aria-describedby on the input).
   */
  descriptionID?: string;
  /**
   * Whether the field is optional. Mutually exclusive with isRequired.
   * @default false
   */
  isOptional?: boolean;
  /**
   * Whether the field is required. Mutually exclusive with isOptional.
   * @default false
   */
  isRequired?: boolean;
  /**
   * Whether the associated input is disabled.
   * @default false
   */
  isDisabled?: boolean;
  /**
   * Icon to display before the label text.
   */
  labelIcon?: ReactNode | IconType;
  /**
   * Status indicator for the field.
   * When set with a message, displays a colored message box below the input.
   */
  status?: FieldStatusInput;
  /**
   * Help text for an info button after the label, named "About {label}".
   */
  labelTooltip?: string;
  /**
   * How the status message is rendered relative to the input.
   * - 'attached': Status sits directly below the input (default, for bordered inputs)
   * - 'detached': Status is a separate element below the field (for checkboxes, switches, sliders)
   * - 'tooltip': No message box; the input surfaces status through a tooltip on its on-field icon
   * @default 'attached'
   */
  statusVariant?: FieldStatusPlacement;
  /**
   * Width of the field. Numbers are treated as pixels, strings are used as-is
   * (e.g. `'100%'`). Sizes the whole field — label, control, and status — so
   * the control and its surrounding chrome stay aligned. Prefer this over
   * setting `width` via `xstyle`/`className`/`style`, which only size the inner
   * control box and leave the label and status at their natural width.
   */
  width?: SizeValue;
  /**
   * The input or control to render inside the field.
   */
  children: ReactNode;
}

/**
 * A form field wrapper that provides label and description.
 *
 * @example
 * ```
 * const id = useId();
 * const descID = useId();
 * <Field label="Email" description="We'll never share your email" inputID={id} descriptionID={descID}>
 *   <input id={id} aria-describedby={descID} />
 * </Field>
 * ```
 */
export function Field({
  label,
  isLabelHidden = false,
  description,
  inputID,
  labelID,
  isGroupLabel = false,
  descriptionID,
  isOptional = false,
  isRequired = false,
  isDisabled = false,
  labelIcon,
  status,
  labelTooltip,
  statusVariant = 'attached',
  width,
  xstyle,
  children,
  className,
  style,
  ref,
  ...props
}: FieldProps) {
  const {direction} = use(FormLayoutContext);
  const isHorizontalLabels = direction === 'horizontal-labels';

  const resolvedDescriptionID =
    descriptionID ?? (description ? `${inputID}-desc` : undefined);
  const resolvedMessageID =
    status?.messageID ?? (status?.message ? `${inputID}-status` : undefined);

  useDevWarning(
    'Field',
    'isOptional and isRequired are mutually exclusive. isOptional takes precedence.',
    isOptional && isRequired,
  );

  const labelNode = (
    <FieldLabel
      label={label}
      inputID={inputID}
      labelID={labelID}
      isGroupLabel={isGroupLabel}
      isLabelHidden={isLabelHidden}
      isDisabled={isDisabled}
      isOptional={isOptional}
      isRequired={isRequired}
      labelIcon={labelIcon}
      labelTooltip={labelTooltip}
      description={isHorizontalLabels ? undefined : description}
      descriptionID={isHorizontalLabels ? undefined : resolvedDescriptionID}
    />
  );

  // The 'tooltip' variant surfaces status through the input's on-field icon
  // tooltip, so Field renders no message box for it. Without a FieldStatus
  // nothing would speak the message, so Field announces it on the same
  // channel and timing FieldStatus uses: placement changes where the message
  // is shown, not whether a screen-reader user hears it.
  useFieldStatusAnnouncement(
    statusVariant === 'tooltip' ? status?.message : undefined,
    status?.type,
  );
  const statusNode =
    status?.message && statusVariant !== 'tooltip' ? (
      <FieldStatus
        type={status.type}
        message={status.message}
        id={resolvedMessageID}
        variant={statusVariant}
        xstyle={
          statusVariant === 'attached' ? styles.attachedStatusLayer : undefined
        }
      />
    ) : null;

  // ─── Horizontal-labels mode ───────────────────────────────────────────
  // Use display:contents so the parent grid's `auto 1fr` columns place
  // the label in column 1 and the input group in column 2. Description
  // and status are grouped with the input in column 2.
  // The label wrapper gets top padding to align label text with input text.
  if (isHorizontalLabels) {
    return (
      <div
        ref={ref}
        {...props}
        {...mergeProps(
          themeProps('field', {layout: 'horizontal-labels'}),
          stylex.props(styles.horizontalLabels, xstyle),
          className,
          style,
        )}>
        <div {...stylex.props(styles.horizontalLabelAlign)}>{labelNode}</div>
        <div {...stylex.props(styles.inputStatusWrapper)}>
          {description &&
            (isLabelHidden ? (
              <VisuallyHidden id={resolvedDescriptionID}>
                {description}
              </VisuallyHidden>
            ) : (
              <Text
                type="supporting"
                display="block"
                id={resolvedDescriptionID}>
                {description}
              </Text>
            ))}
          {children}
          {statusNode}
        </div>
      </div>
    );
  }

  // ─── Default mode (vertical / horizontal) ─────────────────────────────
  return (
    <div
      ref={ref}
      {...mergeProps(
        themeProps('field'),
        stylex.props(
          styles.container,
          !isLabelHidden && styles.containerGap,
          width != null && dynamicStyles.width(width),
          xstyle,
        ),
        className,
        style,
      )}
      {...props}>
      {labelNode}
      {statusVariant === 'attached' ? (
        <div {...stylex.props(styles.inputStatusWrapper)}>
          {children}
          {statusNode}
        </div>
      ) : (
        <>
          {children}
          {statusNode}
        </>
      )}
    </div>
  );
}

Field.displayName = 'Field';

// Copyright (c) Meta Platforms, Inc. and affiliates.

'use client';

/**
 * @file FieldLabel.tsx
 * @input Uses React, Icon, IconType, InfoTip, useComponentTranslator, FormLayoutContext
 * @output Exports FieldLabel component, FieldLabelProps
 * @position Core label implementation; used by Field, CheckboxInput, Switch
 *
 * SYNC: When modified, update these files to stay in sync:
 * - /packages/core/src/Field/Field.doc.mjs (props table, features, implementation notes)
 * - /packages/core/src/Field/index.ts (exports if types change)
 * - /packages/core/src/FormLayout/FormLayoutContext.ts (defaultOptionality drives the indicator)
 * - /packages/cli/assets/templates/blocks/components/Field/ (showcase blocks)
 * - /packages/core/locales/en.json (@astryx.field.required / @astryx.field.optional / @astryx.field.labelTooltip)
 */

import {use, useMemo, useRef, type ReactNode, type RefObject} from 'react';
import * as stylex from '@stylexjs/stylex';
import type {BaseProps} from '@astryxdesign/core/BaseProps';
import {mergeProps} from '@astryxdesign/core/utils';

import {
  colorVars,
  fontWeightVars,
  spacingVars,
  typographyVars,
  typeScaleVars,
} from '@astryxdesign/core/theme/tokens.stylex';
import {renderIconSlot} from '@astryxdesign/core/Icon';
import type {IconType} from '@astryxdesign/core/Icon';
import {InfoTip} from '@astryxdesign/core/InfoTip';
import {themeProps} from '@astryxdesign/core/utils';
import {useInputContainer} from '@astryxdesign/core/hooks';
import {FormLayoutContext} from '@astryxdesign/core/FormLayout';
import {registerEnglishFallback} from '../i18n/englishFallback';
import {useComponentTranslator} from '../i18n/useComponentTranslator';
import english from '../i18n/generated-english/Field/FieldLabel.generated';

registerEnglishFallback(english);

const styles = stylex.create({
  // The label and its description read as a single block, with no space
  // between them. They need a wrapper of their own to get that: as bare
  // siblings they pick up the column gap of whichever caller holds them
  // (Field, CheckboxInput, Switch), which is the spacing meant to separate
  // the label group from the control below it.
  labelGroup: {
    display: 'flex',
    flexDirection: 'column',
  },
  // A hidden label group must not take a slot in the caller's layout, or an
  // empty box would draw the caller's gap around nothing. Dropping the
  // wrapper box leaves the sr-only children out of flow directly under the
  // caller, so the group occupies no space at all.
  labelGroupHidden: {
    display: 'contents',
  },
  label: {
    display: 'flex',
    alignItems: 'center',
    gap: spacingVars['--spacing-1'],
    fontFamily: typographyVars['--font-family-body'],
    fontSize: typeScaleVars['--text-label-size'],
    lineHeight: typeScaleVars['--text-label-leading'],
    fontWeight: fontWeightVars['--font-weight-medium'],
    color: colorVars['--color-text-secondary'],
    cursor: {
      default: 'pointer',
      ':is(:disabled,[aria-disabled="true"])': 'default',
    },
  },
  labelDisabled: {
    color: colorVars['--color-text-disabled'],
    cursor: 'default',
  },
  // A button inside a label also activates the label's control, so the info
  // button sits outside it, in one row with the label.
  labelRow: {
    display: 'inline-flex',
    alignItems: 'center',
    // In a block label cell, keep the row's top on the cell's top, not on a
    // text baseline.
    verticalAlign: 'top',
    gap: spacingVars['--spacing-1'],
  },
  // With a hidden label the row takes no slot in the caller's layout.
  labelRowHidden: {
    display: 'contents',
  },
  // A hidden label's info button takes no layout slot. While it has keyboard
  // focus, it moves into flow above the control. There nothing covers or clips
  // it. It stays positioned, because InfoTip's touch band needs a positioned
  // host.
  infoTipHidden: {
    position: {default: 'absolute', ':focus-visible': 'relative'},
    alignSelf: 'flex-start',
    clip: {default: 'rect(0, 0, 0, 0)', ':focus-visible': 'auto'},
    overflow: {default: 'hidden', ':focus-visible': 'visible'},
    whiteSpace: 'nowrap',
  },
  srOnly: {
    borderStyle: 'none',
    clip: 'rect(0, 0, 0, 0)',
    height: 1,
    insetInlineStart: 0,
    margin: -1,
    overflow: 'hidden',
    padding: 0,
    pointerEvents: 'none',
    position: 'absolute',
    top: 0,
    userSelect: 'none',
    whiteSpace: 'nowrap',
    width: 1,
  },
  optionalRequired: {
    fontWeight: fontWeightVars['--font-weight-normal'],
    fontSize: typeScaleVars['--text-supporting-size'],
    lineHeight: typeScaleVars['--text-supporting-leading'],
    color: colorVars['--color-text-secondary'],
  },
  description: {
    fontFamily: typographyVars['--font-family-body'],
    fontSize: typeScaleVars['--text-supporting-size'],
    lineHeight: typeScaleVars['--text-supporting-leading'],
    fontWeight: fontWeightVars['--font-weight-normal'],
    color: colorVars['--color-text-secondary'],
  },
  // When the description forwards clicks to a click-activatable control
  // (checkbox/switch), it reads as part of the same hit target as the label.
  descriptionClickable: {
    cursor: {
      default: 'pointer',
      ':is(:disabled,[aria-disabled="true"])': 'default',
    },
  },
});

export interface FieldLabelProps extends BaseProps<HTMLLabelElement> {
  /** Ref forwarded to the root element */
  ref?: React.Ref<HTMLLabelElement>;
  /**
   * Label text (always rendered for accessibility).
   */
  label: string;
  /**
   * ID of the input element this label points AT (rendered as `htmlFor` on the
   * label). This is *not* the id of the label element itself — see
   * `labelID` for that.
   */
  inputID: string;
  /**
   * The `id` applied TO the label element itself (not the element it points
   * at — that's `inputID`). A grouping control (e.g. `role="radiogroup"`) can
   * reference this via `aria-labelledby` to take the label as its accessible
   * name.
   */
  labelID?: string;
  /**
   * When true, the field wraps a *group* of controls (e.g. a radiogroup)
   * rather than a single input. In that case the label is rendered as a
   * `<span>` instead of a `<label>` — a `<label>` semantically names one form
   * control and can't be associated with a group, so it must not be a literal
   * label element. The group takes the label as its name via
   * `labelID` + `aria-labelledby`.
   * @default false
   */
  isGroupLabel?: boolean;
  /**
   * Whether to visually hide the label and description (still accessible
   * to screen readers). When hidden, the entire label group is rendered
   * with sr-only styles and takes up no layout space.
   * @default false
   */
  isLabelHidden?: boolean;
  /**
   * Whether the associated input is disabled.
   * @default false
   */
  isDisabled?: boolean;
  /**
   * Whether the field is optional. Mutually exclusive with isRequired.
   * @default false
   */
  isOptional?: boolean;
  /**
   * Whether the field is required. Mutually exclusive with isOptional.
   * @default false
   */
  isRequired?: boolean;
  /**
   * Icon to display before the label text.
   */
  labelIcon?: ReactNode | IconType;
  /**
   * Help text for an info button after the label, named "About {label}".
   */
  labelTooltip?: string;
  /**
   * Description displayed below the label. Hidden along with the label
   * when isLabelHidden is true.
   */
  description?: ReactNode;
  /**
   * ID for the description element (for aria-describedby on the input).
   */
  descriptionID?: string;
}

/**
 * Label + description group for form fields. Handles sr-only hiding,
 * disabled styling, optional/required indicators, icons, and tooltips.
 *
 * When `isLabelHidden` is true the entire group uses sr-only positioning
 * so it takes up zero layout space — no wrapper div left in flow.
 *
 * @example
 * ```
 * <FieldLabel label="Email" inputID={inputId} description="We won't share it" />
 * <FieldLabel label="Search" inputID={inputId} isLabelHidden />
 * ```
 */
export function FieldLabel({
  label,
  inputID,
  labelID,
  isGroupLabel = false,
  isLabelHidden = false,
  isDisabled = false,
  isOptional = false,
  isRequired = false,
  labelIcon,
  labelTooltip,
  description,
  descriptionID,
  className,
  style,
  xstyle,
  ref,
  ...rest
}: FieldLabelProps) {
  const t = useComponentTranslator();
  const {defaultOptionality} = use(FormLayoutContext);

  // A form-level `defaultOptionality` means "only the exception is marked": a
  // field that merely restates the form's default shows no indicator, and only
  // a deviation from it does. This is the *visible indicator* only; the
  // matching `aria-required` is resolved on each control (see
  // useResolvedRequired) so the unmarked majority is still announced.
  //
  //   defaultOptionality  isRequired            isOptional
  //   'optional'          → required indicator  → (matches default, hidden)
  //   'required'          → (matches, hidden)   → optional indicator
  //   unset               → required indicator  → optional indicator
  const showRequired = isRequired && defaultOptionality !== 'required';
  const showOptional = isOptional && defaultOptionality !== 'optional';
  const statusText = showOptional
    ? t('@astryx.field.optional')
    : showRequired
      ? t('@astryx.field.required')
      : null;

  // A group label (e.g. for a radiogroup) must not be a literal `<label>`
  // element: a `<label>` semantically names a single form control and can't be
  // associated with a group. Render it as a `<span>` instead, keeping all the
  // label styling and slots. The group references it via `aria-labelledby`.
  const LabelElement = isGroupLabel ? 'span' : 'label';

  // Clicking the description forwards to the associated control, so the whole
  // label area (label text + description) is one hit target — mirroring native
  // `<label>` click behavior, which the description can't get from `htmlFor`
  // because it stays a sibling `<span>` (nesting it in the `<label>` would fold
  // it into the control's accessible name and double-announce it alongside
  // `aria-describedby`). A group label names a group, not one control, so it
  // has nothing to forward to.
  const forwardsDescriptionClick = !isGroupLabel && inputID != null;

  // Reuse `useInputContainer` — the same hook input wrappers use to forward
  // clicks on non-interactive chrome to their control. It skips nested
  // interactive content (a link/button inside a ReactNode description) and
  // guards against forwarding during text selection, so the description needs
  // no bespoke click logic. The "input" is resolved from `inputID` lazily via
  // a ref-shaped object, since FieldLabel points at the control by id rather
  // than holding a ref to it.
  const descriptionRef = useRef<HTMLSpanElement>(null);
  const controlRef = useMemo<RefObject<HTMLElement | null>>(
    () => ({
      get current() {
        return inputID == null
          ? null
          : (descriptionRef.current?.ownerDocument.getElementById(inputID) ??
              null);
      },
      set current(_value) {},
    }),
    [inputID],
  );
  const descriptionClickProps = useInputContainer({
    containerRef: descriptionRef,
    inputRef: controlRef,
    disabled: !forwardsDescriptionClick,
  });

  const labelContent = (
    <>
      {labelIcon && renderIconSlot(labelIcon, {size: 'sm', color: 'inherit'})}
      {label}
      {statusText && (
        <span {...stylex.props(styles.optionalRequired)}>
          <span aria-hidden="true"> ∙ </span>
          {statusText}
        </span>
      )}
    </>
  );

  const labelElement = (
    <LabelElement
      ref={ref}
      id={labelID}
      // `htmlFor` only applies to a real `<label>` associating with a single
      // control; a group label (span) has no `htmlFor`.
      htmlFor={isGroupLabel ? undefined : inputID}
      {...rest}
      {...mergeProps(
        // A control that knows what kind of label this is passes its own
        // target down (CheckboxInput's `checkbox-label`, Switch's
        // `switch-label`); it arrives as `className` and composes onto this
        // one. The label itself does not describe its own placement — it
        // cannot know it, and any encoding it guessed would be wrong for a
        // caller that arranges labels differently (Field's
        // `horizontal-labels`).
        themeProps('field-label'),
        stylex.props(
          styles.label,
          isDisabled && styles.labelDisabled,
          isLabelHidden && styles.srOnly,
          xstyle,
        ),
        className,
        style,
      )}>
      {labelContent}
    </LabelElement>
  );

  const labelWithHelp = labelTooltip ? (
    <span
      {...stylex.props(
        styles.labelRow,
        isLabelHidden && styles.labelRowHidden,
      )}>
      {labelElement}
      <InfoTip
        content={labelTooltip}
        label={t('@astryx.field.labelTooltip', {label})}
        xstyle={isLabelHidden ? styles.infoTipHidden : undefined}
      />
    </span>
  ) : (
    labelElement
  );

